1	/** Process exit evidence retained by the Aspire MCP smoke. */
2	export interface AspireMcpExit {
3	  readonly code: number | null;
4	  readonly signal: string | null;
5	  readonly graceful: boolean;
6	}
7	
8	/** Generated MCP entry point proved by the smoke. */
9	export interface AspireMcpEntryPoint {
10	  readonly source: '.mcp.json';
11	  readonly command: string;
12	  readonly args: readonly string[];
13	  readonly cwd: string;
14	}
15	
16	/** One transport session used by the smoke orchestration. */
17	export interface AspireMcpTransport {
18	  initialize(): Promise<{ readonly name: string; readonly version: string }>;
19	  listTools(): Promise<readonly string[]>;
20	  callTool(name: string, args?: Readonly<Record<string, unknown>>): Promise<unknown>;
21	  close(): Promise<AspireMcpExit>;
22	  transcript(): readonly unknown[];
23	}
24	
25	/** Time limits for each locked Aspire MCP lifecycle stage. */
26	export interface AspireMcpTimeouts {
27	  initializeMs: number;
28	  toolsListMs: number;
29	  toolCallMs: number;
30	  wholeGateMs: number;
31	}
32	
33	/** Runtime facts supplied by the gate edge. */
34	export interface AspireMcpSmokeInput {
35	  readonly cliVersion: string;
36	  readonly scaffoldPin: string;
37	  readonly entryPoint: AspireMcpEntryPoint;
38	  readonly appHostPath: string;
39	  readonly dashboardUrl: string;
40	  readonly database: string;
41	  readonly appResource: string;
42	  readonly serviceResource: string;
43	  readonly secretValues: readonly string[];
44	  readonly transcript: string;
45	}
46	
47	/** Injectable IO seams used by unit tests and the gate entry point. */
48	export interface AspireMcpSmokeDependencies {
49	  readonly createTransport: (entryPoint: AspireMcpEntryPoint) => Promise<AspireMcpTransport>;
50	  readonly describeResources: () => Promise<readonly string[]>;
51	  readonly persist: (
52	    receipt: AspireMcpSmokeReceipt,
53	    transcript: readonly unknown[],
54	  ) => Promise<void>;
55	  readonly realPath?: (path: string) => Promise<string>;
56	  readonly now: () => Date;
57	  timeouts: AspireMcpTimeouts;
58	}
59	
60	/** Exact semantic receipt retained beside the durable lifecycle receipt. */
61	export interface AspireMcpSmokeReceipt {
62	  readonly receipt: 'aspire-mcp-smoke';
63	  readonly capturedAt: string;
64	  readonly cliVersion: string;
65	  readonly scaffoldPin: string;
66	  readonly entryPoint: AspireMcpEntryPoint;
67	  readonly serverInfo: { readonly name: string; readonly version: string };
68	  readonly appHost: {
69	    readonly path: string;
70	    readonly inScope: boolean;
71	    readonly selected: boolean;
72	  };
73	  readonly toolsExpected: readonly string[];
74	  readonly toolsObserved: readonly string[];
75	  readonly toolsMissing: readonly string[];
76	  readonly toolsExtra: readonly string[];
77	  readonly documentedUnobserved: readonly string[];
78	  readonly documentedUnobservedObserved: readonly string[];
79	  readonly baselineDiff: { readonly added: readonly string[]; readonly removed: readonly string[] };
80	  readonly doctor: {
81	    readonly cliVersion: string;
82	    readonly currentVersion: string;
83	    readonly summary: {
84	      readonly passed: number;
85	      readonly warnings: number;
86	      readonly failed: number;
87	    };
88	  };
89	  readonly visibility: {
90	    readonly expectedVisible: readonly string[];
91	    readonly expectedMcpExcluded: readonly string[];
