308	async function timed<T>(label: string, timeoutMs: number, operation: () => Promise<T>): Promise<T> {
309	  let timeout: number | undefined;
310	  try {
311	    return await Promise.race([
312	      operation(),
313	      new Promise<T>((_, reject) => {
314	        timeout = setTimeout(
315	          () => reject(new Error(`${label} timed out after ${timeoutMs}ms`)),
316	          timeoutMs,
317	        );
318	      }),
319	    ]);
320	  } finally {
321	    if (timeout !== undefined) clearTimeout(timeout);
322	  }
