11	  if (!Array.isArray(entries)) throw new Error('list_apphosts omitted inScope[]');
12	  return {
13	    inScope: entries.map((entry) => {
14	      const path = Reflect.get(record(entry, 'AppHost entry'), 'appHostPath');
15	      if (typeof path !== 'string') throw new Error('AppHost entry omitted appHostPath');
16	      return path;
