21	/** Realpath-compare the MCP AppHost list with the suite-owned AppHost. */
22	export async function matchingAppHosts(
23	  paths: readonly string[],
24	  expected: string,
25	  dependencies: AspireMcpSmokeDependencies,
26	): Promise<string[]> {
